package com.lolzcloud.mobile;

import android.app.*;
import android.graphics.drawable.GradientDrawable;
import android.os.*;
import android.text.*;
import android.view.*;
import android.widget.*;
import java.io.IOException;
import java.util.Arrays;
import java.util.concurrent.*;

/** Native, explicit cloud read/replace/restore. Never opens or tears down a music WebView. */
final class CloudProfileDialog {
    interface Restore { void preview(String json,CloudProfileApi.Identity owner); }
    private final Activity activity;private final LibraryStore store;private final Restore restore;private final Runnable login;private final CloudProfileApi api;
    private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private final int panel,ink,muted,accent;private AlertDialog dialog,confirmation;private TextView status,error;private EditText password;private Button read,upload,download,cancel,signIn;
    private CloudProfileApi.Snapshot snapshot;private Future<?> task;private volatile int generation;private boolean busy;private volatile boolean closed;private volatile char[] pendingPassword;
    CloudProfileDialog(Activity activity,LibraryStore store,int panel,int ink,int muted,int accent,Restore restore,Runnable login){this(activity,store,panel,ink,muted,accent,restore,login,new CloudProfileApi());}
    CloudProfileDialog(Activity activity,LibraryStore store,int panel,int ink,int muted,int accent,Restore restore,Runnable login,CloudProfileApi api){this.activity=activity;this.store=store;this.panel=panel;this.ink=ink;this.muted=muted;this.accent=accent;this.restore=restore;this.login=login;this.api=api;}
    void show(){
        LinearLayout body=new LinearLayout(activity);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(24),dp(8),dp(24),dp(12));
        status=label("Проверяем аккаунт и облачную копию…",14,ink);status.setTag("cloud_status");body.addView(status);read=button("Прочитать облако",()->read());read.setTag("cloud_read");body.addView(read);
        TextView hint=label("Парольная фраза остаётся на устройстве. Сервер хранит только зашифрованный профиль. Для восстановления нужен тот же пароль; восстановить забытый пароль нельзя.",13,muted);body.addView(hint);
        password=new EditText(activity);password.setSingleLine(true);password.setTextColor(ink);password.setHintTextColor(muted);password.setHint("Парольная фраза · 10–256 символов");password.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);password.setFilters(new InputFilter[]{new InputFilter.LengthFilter(256)});password.setMinHeight(dp(52));password.setTag("cloud_password");password.setContentDescription("Парольная фраза облачной копии");body.addView(password);
        download=button("Открыть копию для восстановления",()->decrypt());download.setTag("cloud_restore");body.addView(download);upload=button("Сохранить текущий профиль в облаке",()->prepareUpload());upload.setTag("cloud_save");body.addView(upload);
        cancel=button("Отменить операцию",()->cancelOperation("Операция отменена. Прочитай облако снова."));cancel.setTag("cloud_cancel");body.addView(cancel);
        signIn=button("Войти через Lolzteam",()->{close();login.run();});signIn.setVisibility(View.GONE);body.addView(signIn);error=label("",13,ink);error.setTag("cloud_error");error.setVisibility(View.GONE);body.addView(error);
        ScrollView scroll=new ScrollView(activity);scroll.addView(body);dialog=new AlertDialog.Builder(activity).setTitle("Облачный профиль").setView(scroll).setNegativeButton("Закрыть",null).create();dialog.setOnDismissListener(ignored->close());dialog.show();GradientDrawable background=new GradientDrawable();background.setColor(panel);background.setCornerRadius(dp(20));dialog.getWindow().setBackgroundDrawable(background);dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);read();main.post(ownerWatch);
    }
    private final Runnable ownerWatch=new Runnable(){public void run(){if(closed)return;if(snapshot!=null&&!api.current(snapshot.owner))cancelOperation("Аккаунт изменился. Прочитай облако снова.");main.postDelayed(this,500);}};
    private void read(){if(closed||busy)return;final int ticket=begin("Читаем облачную копию…");snapshot=null;password.setText("");task=worker.submit(()->{try{CloudProfileApi.Snapshot value=api.read();main.post(()->{if(!valid(ticket))return;if(!api.current(value.owner)){cancelOperation("Аккаунт изменился. Прочитай облако снова.");return;}snapshot=value;busy=false;status.setText("Аккаунт: "+value.name+"\n"+(value.envelope==null?"Облачной копии пока нет":"Копия обновлена: "+android.text.format.DateFormat.format("dd.MM.yyyy HH:mm",value.updatedAt))+"\nВерсия копии: "+value.revision);signIn.setVisibility(View.GONE);controls();});}catch(Exception failure){failed(ticket,failure,true);}});}
    private void decrypt(){if(!ready()||snapshot.envelope==null)return;final char[] phrase=phrase();if(phrase==null)return;final CloudProfileApi.Snapshot value=snapshot;final int ticket=begin("Открываем копию на устройстве…");pendingPassword=phrase;
        task=worker.submit(()->{try{api.verify(value.owner);String json=ProfileCrypto.decrypt(value.envelope,phrase);store.previewProfile(json);api.verify(value.owner);main.post(()->{if(!valid(ticket))return;if(!api.current(value.owner)){cancelOperation("Аккаунт изменился. Копия не применена.");return;}close();restore.preview(json,value.owner);});}catch(Exception failure){failed(ticket,failure,false);}finally{Arrays.fill(phrase,'\0');if(pendingPassword==phrase)pendingPassword=null;}});
    }
    private void prepareUpload(){if(!ready())return;final char[] phrase=phrase();if(phrase==null)return;final CloudProfileApi.Snapshot value=snapshot;final int ticket=begin("Готовим переносимый профиль…");pendingPassword=phrase;
        task=worker.submit(()->{try{String json=store.exportProfile(),summary=store.previewProfile(json);api.verify(value.owner);main.post(()->{if(!valid(ticket))return;if(!api.current(value.owner)){cancelOperation("Аккаунт изменился. Ничего не сохранено.");return;}confirmation=new AlertDialog.Builder(activity).setTitle(value.envelope==null?"Создать облачную копию?":"Заменить облачную копию?").setMessage("Аккаунт: "+value.name+"\n"+summary+"\nРазмер данных: "+json.getBytes(java.nio.charset.StandardCharsets.UTF_8).length+" байт.\n"+(value.envelope==null?"На сервер отправится только зашифрованный профиль.":"Существующая копия будет заменена. Если другое устройство уже изменило её, сохранение будет отклонено.")).setNegativeButton("Отмена",(d,w)->cancelOperation("Сохранение отменено." )).setPositiveButton(value.envelope==null?"Создать":"Заменить",(d,w)->save(ticket,value,json,phrase)).create();confirmation.setOnCancelListener(d->cancelOperation("Сохранение отменено."));confirmation.show();});}catch(Exception failure){Arrays.fill(phrase,'\0');if(pendingPassword==phrase)pendingPassword=null;failed(ticket,failure,true);}});
    }
    private void save(int ticket,CloudProfileApi.Snapshot previous,String json,char[] phrase){if(!valid(ticket)||!api.current(previous.owner)){cancelOperation("Аккаунт изменился. Ничего не сохранено.");return;}status.setText("Шифруем и сохраняем копию…");task=worker.submit(()->{try{ProfileCrypto.Envelope envelope=ProfileCrypto.encrypt(json,phrase);CloudProfileApi.Snapshot value=api.save(previous,envelope,()->valid(ticket));main.post(()->{if(!valid(ticket))return;if(!api.current(value.owner)){cancelOperation("Аккаунт изменился. Прочитай облако снова.");return;}busy=false;snapshot=value;status.setText("Сохранено для "+value.name+"\nВерсия копии: "+value.revision);controls();});}catch(Exception failure){failed(ticket,failure,true);}finally{Arrays.fill(phrase,'\0');if(pendingPassword==phrase)pendingPassword=null;}});}
    private boolean ready(){if(closed||busy||snapshot==null)return false;if(!api.current(snapshot.owner)){cancelOperation("Аккаунт изменился. Прочитай облако снова.");return false;}return true;}
    private char[] phrase(){char[] value=new char[password.length()];TextUtils.getChars(password.getText(),0,password.length(),value,0);try{ProfileCrypto.validatePassword(value);password.setText("");error.setVisibility(View.GONE);return value;}catch(IOException invalid){Arrays.fill(value,'\0');error.setText(invalid.getMessage());error.setVisibility(View.VISIBLE);return null;}}
    private int begin(String message){int ticket=++generation;busy=true;error.setText("");error.setVisibility(View.GONE);status.setText(message);controls();return ticket;}
    private boolean valid(int ticket){return !closed&&generation==ticket;}
    private void controls(){if(read==null)return;read.setEnabled(!busy);upload.setEnabled(!busy&&snapshot!=null);download.setEnabled(!busy&&snapshot!=null&&snapshot.envelope!=null);password.setEnabled(!busy&&snapshot!=null);cancel.setVisibility(busy?View.VISIBLE:View.GONE);}
    private void failed(int ticket,Exception failure,boolean invalidate){main.post(()->{if(!valid(ticket))return;busy=false;if(invalidate||failure instanceof CloudProfileApi.ApiError&&(((CloudProfileApi.ApiError)failure).status==401||((CloudProfileApi.ApiError)failure).status==403||((CloudProfileApi.ApiError)failure).status==409))snapshot=null;status.setText("Операция не завершена");error.setText(failure.getMessage()==null?"Попробуй прочитать облако снова":failure.getMessage());error.setVisibility(View.VISIBLE);signIn.setVisibility(failure instanceof CloudProfileApi.ApiError&&(((CloudProfileApi.ApiError)failure).status==401||((CloudProfileApi.ApiError)failure).status==403)?View.VISIBLE:View.GONE);controls();});}
    void suspend(){if(!closed)cancelOperation("Операция приостановлена. Прочитай облако снова.");}
    private void cancelOperation(String message){generation++;if(task!=null)task.cancel(true);api.cancel();char[] phrase=pendingPassword;if(phrase!=null)Arrays.fill(phrase,'\0');pendingPassword=null;snapshot=null;busy=false;if(password!=null)password.setText("");if(confirmation!=null){confirmation.dismiss();confirmation=null;}if(status!=null){status.setText(message);controls();}}
    void close(){if(closed)return;closed=true;cancelOperation("Операция отменена");main.removeCallbacksAndMessages(null);worker.shutdownNow();if(dialog!=null&&dialog.isShowing())dialog.dismiss();}
    private int dp(float value){return Math.round(value*activity.getResources().getDisplayMetrics().density);}
    private TextView label(String text,int size,int color){TextView view=new TextView(activity);view.setText(text);view.setTextColor(color);view.setTextSize(size);view.setPadding(0,dp(6),0,dp(8));view.setLineSpacing(dp(3),1);return view;}
    private Button button(String text,Runnable action){Button button=new Button(activity);button.setText(text);button.setTextColor(ink);button.setAllCaps(false);button.setMinHeight(dp(48));button.setOnClickListener(v->action.run());return button;}
}
